# phrase locate on text ignoring whitespace & punctuation while preserving offsets
punct=re.compile(r'[«»“”"\'’.,;:!?…()\[\]{}—–-]')
def norm(s):return re.sub(r'\s+',' ',punct.sub(' ',s)).strip().lower()
def pos(text,phrase,after=0):
 tokens=[(m.start(),m.end(),norm(m[0])) for m in re.finditer(r'\S+',text) if norm(m[0])]
 target=norm(phrase)
 for i,(st,en,tok) in enumerate(tokens):
  if st<after:continue
  joined=tok;j=i
  while len(joined)<len(target) and j+1<len(tokens):j+=1;joined+=' '+tokens[j][2]
  if joined==target:return st
 raise ValueError((phrase,text[:120]))
scenes=sorted(plan['scenes'],key=lambda x:x['id']);rows={}
for secid,sec in sections.items():
 ss=[s for s in scenes if s['script_section_id']==secid];text=sec['text'];poss=[];cur=0
 for s in ss:
  ix=pos(text,starts[s['id']],cur);poss.append(ix);cur=ix+1
 for j,s in enumerate(ss):
  a=poss[j];b=poss[j+1] if j+1<len(ss) else len(text)
  rows[s['id']]={'scene':s['id'],'section':secid,'start_phrase':starts[s['id']],'narration':text[a:b].strip(),'full_section':text,'visual_intent':s['description']}
